const onLiveServer=location.port==='8787',LIVE_URL=onLiveServer?'':(localStorage.getItem('supit-live-url')||'http://127.0.0.1:8787');let mode=localStorage.getItem('supit-mode')||(onLiveServer?'live':'rehearsal'),base='';const live=()=>remote&&state?.mode==='live';
async function api(path,body){const r=await fetch(base+'/api/'+path,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{'Authorization':'Bearer '+token}:{})},...(body?{body:JSON.stringify(body)}:{})});if(!r.ok){if(r.status===401||r.status===403)throw Error('A shared token is required. Open the session menu to connect.');const e=await r.json().catch(()=>({}));throw Error(e.error||e.detail?.message||'The control plane could not complete that action.');}return r.json()}
async function sign(doc){const body={...doc,signing_algorithm:'Ed25519',public_key:publicKey};return {...body,signature:b64(await crypto.subtle.sign('Ed25519',signingKey.privateKey,new TextEncoder().encode(canonical(body))))}}
