async function initializeBrowser(){const config=await fetch('/contract.json').then(r=>r.json());state={contract:config.contract,contract_hash:config.hash};contractYaml=await fetch('/contract.yaml').then(r=>r.text());signingKey=await crypto.subtle.generateKey('Ed25519',true,['sign','verify']);publicKey=b64(await crypto.subtle.exportKey('raw',signingKey.publicKey));await record('session_started',{contract_hash:config.hash,synthetic:true,description:'Browser rehearsal started. No live GPU connections. Key is held in this browser for this session only.'});tickBrowser();}
