function chart(){const data=state.traffic.series.slice(-chartRange);const width=600,height=151,top=10,bottom=127,left=27,right=590,peak=Math.max(0,...data.map(d=>(d.a||0)+(d.b||0)+(d.serverless||0))),max=live()?Math.max(3,Math.ceil(peak*1.25/3)*3):15;const y=v=>bottom-v/max*(bottom-top);const x=i=>left+i/(Math.max(data.length-1,1))*(right-left);let out='';[0,1,2,3].map(i=>max*i/3).forEach(v=>out+=`<line class="chart-grid" x1="27" x2="590" y1="${y(v)}" y2="${y(v)}"/><text x="5" y="${y(v)+3}">${v}</text>`);if(data.length){const bands=[{key:'a',color:'#95b789'},{key:'b',color:'#d0dfb9'},{key:'serverless',color:'#e7cc9d'}];bands.forEach((b,j)=>{const low=d=>bands.slice(0,j).reduce((s,k)=>s+(d[k.key]||0),0);const high=d=>low(d)+(d[b.key]||0);const points=data.map((d,i)=>`${x(i).toFixed(1)},${y(high(d)).toFixed(1)}`).concat(data.map((d,i)=>`${x(i).toFixed(1)},${y(low(d)).toFixed(1)}`).reverse());out+=`<polygon points="${points.join(' ')}" fill="${b.color}" opacity=".77"/>`;});const a=data.map((d,i)=>`${i?'L':'M'}${x(i).toFixed(1)} ${y(d.a).toFixed(1)}`).join(' ');out+=`<path d="${a}" stroke="#7b9e6b" stroke-width="1.3" fill="none"/>`;[0,.25,.5,.75,1].forEach(f=>{const i=Math.round((data.length-1)*f);out+=`<text x="${left+f*(right-left)}" y="147" text-anchor="${f===0?'start':f===1?'end':'middle'}">${new Date(data[i].time).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'})}</text>`});}else out+=`<text x="300" y="75" text-anchor="middle">Collecting this session’s ${live()?'':'synthetic '}traffic…</text>`;return `<svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="${live()?'Measured':'Simulated'} requests per second by provider">${out}</svg>`}
function panelHead(title,sub='',right=''){return `<div class="panel-head"><div><h2>${title}</h2>${sub?`<p class="panel-subtitle">${sub}</p>`:''}</div>${right}</div>`}
